// KNN-7x20 Direction Vote 3D
// KNN nearest-neighbour vote on next-bar direction (Euclidean on returns)

k = input(7, "K Neighbors", 1, 30, 1)
featureBars = input(20, "Feature Bars", 5, 50, 1)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagreeThresh = input(0.5, "Disagreement Threshold", 0.1, 1.0, 0.01)
maxHistory = input(300, "Max History", 50, 500, 10)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar raw move r[t] ────────────────────────────────
prevC = close[1]
denom = prevC
if denom == 0 { denom := 0.000000001 }
curR = 0.0
if bar_index > 0 { curR := (close - prevC) / denom }

// ─── Persistent history (returns + closes for labels) ─────
var rHist = array(0)
var cHist = array(0)
array.push(rHist, curR)
array.push(cHist, close)

// ─── KNN Euclidean vote over last FeatureBars returns ─────
var margin = 0.0
var disagreement = 1.0
var bullCt = 0
var bearCt = 0

numBars = array.size(rHist)
tIdx = numBars - 1
warmup = featureBars + 2

if numBars > warmup {
    bestDist = array()
    bestTarg = array()
    ii = 0
    while ii < k {
        array.push(bestDist, 999999.0)
        array.push(bestTarg, 0)
        ii := ii + 1
    }

    sStart = tIdx - maxHistory
    if sStart < warmup { sStart := warmup }
    // F(t) starts at tIdx-featureBars+1; F(s) at s-featureBars+1
    s = sStart
    while s < tIdx {
        // label d(s): +1 if close[s+1] > close[s] else -1 (s+1 <= tIdx, known)
        cS = cHist[s]
        cNext = cHist[s + 1]
        lab = 0 - 1
        if cNext > cS { lab := 1 }

        // Euclidean distance sum_j (F(t)[j]-F(s)[j])^2
        sumSq = 0.0
        f = 0
        while f < featureBars {
            a = rHist[tIdx - featureBars + 1 + f]
            b = rHist[s - featureBars + 1 + f]
            d = a - b
            sumSq := sumSq + d * d
            f := f + 1
        }
        dist = sqrt(sumSq)

        // sorted insert into k-best
        insIdx = 0 - 1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                insIdx := m
                m := k
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = k - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestTarg, m, bestTarg[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestTarg, insIdx, lab)
        }
        s := s + 1
    }

    nbull = 0
    nbear = 0
    m = 0
    while m < k {
        if bestDist[m] < 999999.0 {
            if bestTarg[m] == 1 { nbull := nbull + 1 }
            else { nbear := nbear + 1 }
        }
        m := m + 1
    }
    bullCt := nbull
    bearCt := nbear
    tot = nbull + nbear
    mg = 0.0
    dg = 1.0
    if tot > 0 {
        mg := (nbull - nbear) / tot
        p = nbull / tot
        dg := 4.0 * p * (1.0 - p)
    }
    margin := mg
    disagreement := dg
}

// ─── Dual-agreement conditions (both channels must agree) ──
buyCond = margin > marginThresh and disagreement < disagreeThresh
sellCond = margin < 0 - marginThresh and disagreement < disagreeThresh
buyCondPrev = buyCond[1]
sellCondPrev = sellCond[1]
buySig = buyCond and not buyCondPrev
sellSig = sellCond and not sellCondPrev

// ─── 2D signals (events on edge only) ──────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 3D cones in SAME pane as geometry ─────────────────────
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", "#ff4477", markerSize, 0, "separate")
}

// ─── 2D twin channels (independently readable) ─────────────
plot(margin, "Vote Margin", "#22cc88", 2, "separate")
plot(disagreement, "Disagreement", "#ffd43b", 1, "separate")
hline(0, "#888888", "separate")
hline(0.43, "#22cc88", "separate")
hline(0 - 0.43, "#ff4477", "separate")
hline(0.5, "#ffd43b", "separate")

// ─── 3D form: pillar height = Margin, second cloud = Disagreement ──
// Tall narrow bright pillar = crisp; short wide flat = contested.
plot3d(margin, "Vote Margin Pillars", "bars3d", "#22cc88", "separate")
plot3d(disagreement, "Disagreement Cloud", "scatter", "#ffd43b", "separate")

// Visible Session Volume Value Model
// Volume-profile-on-chart: POC + value area from visible session, breakout signals leaving value.

profileRows = input(24, "Profile Rows", 5, 48, 1)
vaPct = input(70, "Value Area Volume Percent", 50, 90, 1)
sessLen = input(200, "Session Length", 24, 500, 10)
pocExt = input(5, "POC Rail Length Extension", 0, 20, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }
rowH = rng / profileRows

// ─── Persistent bins (literal init only, resized/zeroed per bar) ──
var binVol = array()
var vaInc = array()

// Ensure binVol size matches profileRows
if array.size(binVol) != profileRows {
    binVol := array()
    i = 0
    while i < profileRows {
        array.push(binVol, 0.0)
        i := i + 1
    }
}
if array.size(vaInc) != profileRows {
    vaInc := array()
    i = 0
    while i < profileRows {
        array.push(vaInc, 0.0)
        i := i + 1
    }
}

// Zero bins for this bar's full recompute
i = 0
while i < profileRows {
    array.set(binVol, i, 0.0)
    array.set(vaInc, i, 0.0)
    i := i + 1
}

// ─── Deposit session volume proportionally over overlapped rows ──
k = 0
while k < sessLen {
    bHigh = high[k]
    bLow = low[k]
    bVol = volume[k]
    bRange = bHigh - bLow
    r1 = floor((bLow - ll) / rowH)
    if r1 < 0 { r1 := 0 }
    if r1 > profileRows - 1 { r1 := profileRows - 1 }
    r2 = floor((bHigh - ll) / rowH)
    if r2 < 0 { r2 := 0 }
    if r2 > profileRows - 1 { r2 := profileRows - 1 }
    if bRange <= 0 {
        array.set(binVol, r1, array.get(binVol, r1) + bVol)
    } else {
        if r1 == r2 {
            array.set(binVol, r1, array.get(binVol, r1) + bVol)
        } else {
            r = r1
            while r <= r2 {
                rowTop = ll + (r + 1) * rowH
                rowBot = ll + r * rowH
                ovTop = bHigh
                if rowTop < ovTop { ovTop := rowTop }
                ovBot = bLow
                if rowBot > ovBot { ovBot := rowBot }
                ov = ovTop - ovBot
                if ov > 0 {
                    share = ov / bRange * bVol
                    array.set(binVol, r, array.get(binVol, r) + share)
                }
                r := r + 1
            }
        }
    }
    k := k + 1
}

// ─── Totals + POC (row with max volume) ──────────────────────────
totalVol = array.sum(binVol)
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < profileRows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) * rowH

// ─── Value area: sort rows by volume desc, accumulate to vaPct ───
target = totalVol * vaPct / 100
accum = 0.0
guard = 0
while accum < target and guard < profileRows {
    bestIdx = 0 - 1
    bestVal = 0 - 1.0
    i = 0
    while i < profileRows {
        if array.get(vaInc, i) == 0.0 {
            v = array.get(binVol, i)
            if v > bestVal {
                bestVal := v
                bestIdx := i
            }
        }
        i := i + 1
    }
    if bestIdx < 0 { guard := profileRows }
    if bestIdx >= 0 {
        array.set(vaInc, bestIdx, 1.0)
        accum := accum + bestVal
    }
    guard := guard + 1
}

// VAH = highest included row top, VAL = lowest included row bottom
vaMax = pocBin
vaMin = pocBin
i = 0
while i < profileRows {
    if array.get(vaInc, i) == 1.0 {
        if i > vaMax { vaMax := i }
        if i < vaMin { vaMin := i }
    }
    i := i + 1
}
vahPrice = ll + (vaMax + 1) * rowH
valPrice = ll + vaMin * rowH

// Volume at current price row = terrain height series (dynamic)
closeBin = floor((close - ll) / rowH)
if closeBin < 0 { closeBin := 0 }
if closeBin > profileRows - 1 { closeBin := profileRows - 1 }
volAtClose = array.get(binVol, closeBin)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol * 100 }

// ─── Signals: price leaving value (edge-fired, no repeat outside) ─
insideVA = close >= valPrice and close <= vahPrice
prevInside = close[1] >= valPrice and close[1] <= vahPrice
buySig = close > vahPrice and prevInside
sellSig = close < valPrice and prevInside

if buySig { plotshape(bar_index, low, "Breakout Up", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Breakout Down", "triangledown", "#ff4477") }

if buySig { plotshape_3d(bar_index, low, "Breakout Up", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d") }
if sellSig { plotshape_3d(bar_index, high, "Breakout Down", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d") }

// ─── 2D: same information when 3D is off ─────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(volAtClose, "Row Volume At Close", "#4488ff", 1, "separate")
plot(pocShare, "POC Share %", "#ffd43b", 1, "separate")

box.new(bar_index - sessLen, vahPrice, bar_index + pocExt, valPrice, "#22cc88", "#22cc8811", 1, "VAZONE")

if insideVA { bgcolor("rgba(34,204,136,0.04)") }
if buySig { bgcolor("rgba(34,204,136,0.10)") }
if sellSig { bgcolor("rgba(255,68,119,0.10)") }

// ─── 3D: value sits as terrain, POC as labelled rail ─────────────
plot3d(volAtClose, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d")

// FIX: var lvl = highest(high, 20) froze the value on bar 0 — must be plain assignment recomputed every bar.
// FIX: close[-1] is a future leak — corrected to close > lvl for a confirmed breakout.
// FIX: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine signature — corrected to OakScript positional strings and hex.
// FIX: plot3d(r, "RSI", "surface", "#b48cff", "3d") forces an oscillator into price scene — corrected to pane "separate" per PANE LAW.
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(lvl, "High20", "#ffaa00", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

breakoutLen = input(20, "Breakout Length", 5, 50, 1)
momLen = input(12, "Momentum Length", 2, 50, 1)
expMult = input(1.1, "Vol Expansion Mult", 1.0, 2.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

vol = (high - low) / close
volPrev = (high[1] - low[1]) / close[1]
mom = close - close[momLen]
brkHigh = highest(high[1], breakoutLen)
brkLow = lowest(low[1], breakoutLen)
expansion = vol > volPrev * expMult

var lastDir = 0

rawBuy = close > brkHigh and mom > 0 and expansion
rawSell = close < brkLow and mom < 0 and expansion
buySig = rawBuy and not rawBuy[1] and lastDir[1] != 1
sellSig = rawSell and not rawSell[1] and lastDir[1] != -1

if buySig {
    lastDir := 1
}
if sellSig {
    lastDir := -1
}

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 1, "3d")
}

if expansion {
    bgcolor("#22cc8815")
}
plot(brkHigh, "Breakout High", "#22cc88", 1)
plot(brkLow, "Breakout Low", "#ff4477", 1)
plot(mom, "Momentum", "#33aaff", 1, "separate")
hline(0, "#888888", "separate")
plot3d(brkHigh, "3D Breakout High", "line3d", "#22cc88", "3d", 0)
plot3d(brkLow, "3D Breakout Low", "line3d", "#ff4477", "3d", 1)

baseFlow = input(110, "Base Flow PSI", 20, 250, 1)
critical_threshold = input(150, "Critical Threshold", 50, 300, 1)
spin_factor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
ring_count = input(3, "Ring Count", 1, 5, 1)
ring_expansion_speed = input(2.0, "Ring Expansion Speed", 0.2, 10.0, 0.2)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

range20 = highest(high, 20) - lowest(low, 20) + 0.000001
flowPos = (close - lowest(low, 20)) / range20 * 80
flowVol = (high - low) / close * 1200
flowMom = (close - close[1]) / (close + 0.000001) * 1500
flow_psi = baseFlow - 40 + flowPos + flowVol + flowMom

spin_speed = flow_psi * spin_factor
maxRadius = 6 + ring_count * 6
discSpin = flow_psi * 0.5 + spin_speed * 0.5

var lockVal = 0.0
var rotA = 0.0
var rr1 = 0.0
var rr2 = 0.0
var rr3 = 0.0
var lastTrig = -100000.0

overpressure_state = flow_psi > critical_threshold

if overpressure_state {
  rotA := rotA[1]
} else {
  rotA := rotA[1] + spin_speed * 0.05
}

if overpressure_state {
  lockVal := lockVal[1]
} else {
  lockVal := flow_psi
}

discLevel = overpressure_state and lockVal > 1 ? lockVal : flow_psi

step1 = ring_expansion_speed
step2 = ring_expansion_speed * 0.8
step3 = ring_expansion_speed * 0.6

if overpressure_state {
  rr1 := rr1[1] + step1
} else {
  rr1 := 0.0
}

if overpressure_state {
  rr2 := rr2[1] + step2
} else {
  rr2 := 0.0
}

if overpressure_state {
  rr3 := rr3[1] + step3
} else {
  rr3 := 0.0
}

if rr1 > maxRadius {
  rr1 := 2.0
}

if rr2 > maxRadius {
  rr2 := 2.0
}

if rr3 > maxRadius {
  rr3 := 2.0
}

ringWave = rr1 + rr2 * 0.7 + rr3 * 0.5 + flow_psi * 0.02
spinVel2D = spin_speed + rotA * 0.01

sellSigRaw = overpressure_state and not overpressure_state[1]
buySigRaw = not overpressure_state and overpressure_state[1]
canFire = bar_index - lastTrig[1] > 20
sellSig = sellSigRaw and canFire
buySig = buySigRaw and canFire

if sellSig or buySig {
  lastTrig := bar_index
} else {
  lastTrig := lastTrig[1]
}

if sellSig {
  plotshape(bar_index, high, "Overpressure", "triangledown", "#ff4477")
}

if buySig {
  plotshape(bar_index, low, "Normal", "triangleup", "#22cc88")
}

if sellSig {
  plotshape_3d(bar_index, high, "Overpressure", "conedown", "#ff4477", 1.4 * markerSize, 1, "separate")
}

if buySig {
  plotshape_3d(bar_index, low, "Normal", "coneup", "#22cc88", 1.0 * markerSize, 1, "separate")
}

if sellSig {
  label3d(bar_index, high + (high - low + 1) * 0.6, "OVERPRESSURE", "#ff4477", 2, 2, "separate")
}

plot(flow_psi, "Flow PSI", "#22aaff", 2, "separate")
plot(spinVel2D, "Spin Velocity", "#ffaa22", 1, "separate")
plot(discLevel, "Valve Disc", "#aa66ff", 1, "separate")
hline(critical_threshold, "#ff4477", "separate")
plot3d(discSpin, "Valve Disc", "torus", "#22aaff", "separate")
plot3d(ringWave, "Shockwave Rings", "trail", "#ff4477", "separate", 1)
